import {FACTIONS,TROOPS,loadInputs} from '/src/data.mjs';
import {createInitialState,issueOrder,executeTicks,advanceTurn,getFactionView,exportSave,importSave,SAVE_KEY} from '/src/core.mjs';
const app=document.querySelector('#app');
let inputs,state,selectedFaction='F01',notice='',destination='';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const statusText={PLANNED:'이동 예정',ACTIVE:'이동 중',COMPLETED:'도착',HOLDING:'대기',WAITING_FOR_TILE:'앞 칸이 비기를 기다림',CONTACT:'다른 세력과 접촉 · 정지',EDGE_CONTACT:'길목에서 접촉 · 정지',BLOCKED_INVALID_PATH:'경로가 막혀 정지'};
function act(fn){try{fn();}catch(e){notice=e.message;}state?renderGame():renderStart();}
function load(){act(()=>{state=importSave(localStorage.getItem(SAVE_KEY),inputs);destination=state.armies[state.ui.selectedArmyId]?.currentOrder?.destinationTileId??'';notice='이동 경과와 관측 기록까지 불러왔습니다.';});}
function renderStart(){
  app.innerHTML=`<section class="card start"><div class="eyebrow">삼국지</div><div class="title">첫 세력의 시작</div><p class="sub">조조 · 유비 · 손권, 같은 세계에서 당신의 세력을 선택하세요.</p><div class="choices">${Object.values(FACTIONS).map(f=>`<button class="choice ${selectedFaction===f.id?'selected':''}" style="--accent:${f.color}" data-faction="${f.id}" aria-label="${esc(f.name)} 선택" aria-pressed="${selectedFaction===f.id}"><span class="mark">${f.mark}</span><div class="name">${esc(f.name)}</div><p>${esc(f.concept)}</p></button>`).join('')}</div><div class="actions"><button class="primary" id="start" ${inputs?'':'disabled'}>선택한 세력으로 시작</button><button id="load" ${inputs?'':'disabled'}>진행 불러오기</button></div><p class="notice" role="status">${esc(notice)}</p><p class="note">이동하고 주변을 살펴보세요. 이번 버전에서는 다른 세력과 만나면 멈춥니다. 전투와 도시 정산은 준비 중입니다.</p></section>`;
  app.querySelectorAll('[data-faction]').forEach(b=>b.addEventListener('click',()=>{selectedFaction=b.dataset.faction;renderStart();}));
  app.querySelector('#start').addEventListener('click',()=>act(()=>{state=createInitialState({...inputs,factionId:selectedFaction});state.ui.selectedArmyId=state.factions[selectedFaction].armyIds[1];notice='부대를 선택하고 지도에서 목적지를 누르세요.';}));
  app.querySelector('#load').addEventListener('click',load);
}
const point=([q,r],size=21)=>({x:30+Math.sqrt(3)*size*(q+r/2),y:32+size*1.5*r});
const pos=id=>point(id.split(',').map(Number));
const polygon=p=>Array.from({length:6},(_,i)=>{const a=Math.PI/3*i-Math.PI/6;return `${p.x+20*Math.cos(a)},${p.y+20*Math.sin(a)}`;}).join(' ');
function mapSvg(v){
  const k=v.knowledge,selected=v.ownArmies[v.ui.selectedArmyId];
  const tiles=Object.values(v.tiles).map(t=>{const p=pos(t.tileId);return `<polygon data-tile="${t.tileId}" class="tile ${t.terrainType??''} ${k.tiles[t.tileId].toLowerCase()} ${t.tileId===destination?'selected':''}" points="${polygon(p)}"><title>(${t.tileId}) · ${k.tiles[t.tileId]==='VISIBLE'?'현재 관측':k.tiles[t.tileId]==='REMEMBERED'?'과거에 탐색함':'미탐색'}</title></polygon>`;}).join('');
  const roads=(inputs.map.roads??[]).filter(e=>e.every(p=>k.tiles[p.join(',')]!=='UNEXPLORED')).map(([a,b])=>{const p=point(a),q=point(b);return `<line class="map-decoration" x1="${p.x}" y1="${p.y}" x2="${q.x}" y2="${q.y}" stroke="#b6a481" stroke-width="2" opacity=".5"/>`;}).join('');
  const cities=Object.values(k.cities).map(c=>{const p=pos(c.tileId),f=FACTIONS[c.ownerFactionId];return `<g class="map-decoration ${k.tiles[c.tileId]==='REMEMBERED'?'old-sighting':''}"><rect x="${p.x-9}" y="${p.y-10}" width="18" height="18" fill="${f.color}" stroke="#fff"/><text class="city-label" x="${p.x}" y="${p.y-20}" text-anchor="middle">${esc(c.name)}</text></g>`;}).join('');
  const units=[...Object.values(v.ownArmies).map(a=>({...a,own:true})),...Object.values(k.observedArmies)].map(a=>{const p=pos(a.tileId),label=a.own?v.officers[a.commanderId].name:`${FACTIONS[a.factionId].name} ${TROOPS[a.troopType]}`;return `<g ${a.own?`data-army="${a.armyId}"`:'class="map-decoration"'}><title>${esc(label)}${a.own?` · ${a.troopCount}명`:' · 병력 미상'}</title><circle class="unit-dot" cx="${p.x+10}" cy="${p.y+10}" r="${selected?.armyId===a.armyId?9:7}" fill="${FACTIONS[a.factionId].color}"/><text class="city-label" x="${p.x}" y="${p.y+30}" text-anchor="middle">${esc(a.own?label:TROOPS[a.troopType])}</text></g>`;}).join('');
  const remembered=Object.values(k.lastSeenArmies).filter(a=>!k.observedArmies[a.armyId]).map(a=>{const p=pos(a.tileId);return `<g class="map-decoration old-sighting"><circle cx="${p.x}" cy="${p.y}" r="8" fill="none" stroke="${FACTIONS[a.factionId].color}" stroke-dasharray="3 2"/><title>${FACTIONS[a.factionId].name} ${TROOPS[a.troopType]} · 마지막 관측 ${a.lastSeen.turn}턴 ${a.lastSeen.tick}</title></g>`;}).join('');
  const path=selected?.currentOrder?.pathTileIds.slice(selected.currentOrder.currentPathIndex)??[];
  const route=path.length>1?`<polyline class="map-decoration" points="${path.map(id=>{const p=pos(id);return `${p.x},${p.y}`;}).join(' ')}" fill="none" stroke="#e7bf62" stroke-width="3" stroke-dasharray="6 4"/>`:'';
  const end=point([17,13]);return `<svg class="map" viewBox="0 0 ${end.x+40} ${end.y+50}" role="img" aria-label="이동 지도: 밝은 칸은 현재 관측, 어두운 칸은 과거 탐색, 검은 칸은 미탐색">${tiles}${roads}${route}${cities}${remembered}${units}</svg>`;
}
function order(type){act(()=>{state=issueOrder(state,{armyId:state.ui.selectedArmyId,type,destinationTileId:destination});notice=type==='MOVE'?`(${destination})까지 경로를 정했습니다.`:'현재 위치에서 대기합니다.';});}
function renderGame(){
  // All enemy information below comes from the observation projection.
  const v=getFactionView(state),player=FACTIONS[v.factionId],c=v.ownCities[v.ui.selectedCityId]??Object.values(v.ownCities)[0],a=v.ownArmies[v.ui.selectedArmyId],locked=v.turnPhase!=='PLANNING',k=v.knowledge;
  const seen=Object.values(k.observedArmies),old=Object.values(k.lastSeenArmies).filter(x=>!k.observedArmies[x.armyId]);
  app.innerHTML=`<div class="shell"><header class="top"><div><div class="eyebrow">삼국지 · 이동과 관측</div><div class="title">${player.name}의 첫 판</div><div class="sub">군주 ${esc(v.officers[v.faction.rulerId].name)} · 제 ${v.turnNumber}턴 · 경과 ${v.currentDate}일</div></div><span class="badge">${locked?'명령 실행 중':'명령 준비'}</span></header><div class="world-summary">이동 · 대기 · 관측 · 진행 저장</div><div class="layout"><section class="card mapcard"><div class="city-tabs">${Object.values(v.ownArmies).map(unit=>`<button data-army-select="${unit.armyId}" aria-pressed="${a?.armyId===unit.armyId}">${esc(v.officers[unit.commanderId].name)} · ${TROOPS[unit.troopType]}</button>`).join('')}</div><div class="mapwrap">${mapSvg(v)}</div><div class="statusline"><span class="chip">현재 관측 ${Object.values(k.tiles).filter(t=>t==='VISIBLE').length}칸</span><span class="chip">과거 탐색 ${Object.values(k.tiles).filter(t=>t==='REMEMBERED').length}칸</span><span class="chip">미탐색 ${Object.values(k.tiles).filter(t=>t==='UNEXPLORED').length}칸</span></div><p class="note">지도에서 목적지를 고르고 이동 명령을 내리세요. 점선은 이동 경로, 옅은 원은 상대의 마지막 관측 위치입니다.</p></section><aside class="side"><section class="card"><div class="eyebrow">선택한 부대</div><div class="title">${a?esc(v.officers[a.commanderId].name):'부대 선택'}</div>${a?`<p>${TROOPS[a.troopType]} · ${a.troopCount}명 · 현재 (${a.tileId})</p><p>${statusText[a.currentOrder?.status]??'명령 없음'}${a.movementState?` · 다음 칸 (${a.movementState.toTileId})까지 ${Math.min(100,Math.round(a.movementState.edgeProgress*100))}%`:''}</p>`:''}<form id="move-form"><label for="destination">목적지 좌표</label><input id="destination" name="destination" placeholder="예: 9,3" value="${esc(destination)}" ${locked?'disabled':''}/><div class="actions"><button class="primary" ${locked||!a?'disabled':''}>이동 명령</button><button type="button" id="hold" ${locked||!a?'disabled':''}>대기 명령</button></div></form><div class="actions execution"><button id="day">1일 진행</button><button class="primary" id="turn">${locked?'남은 기간 실행':'10일 실행'}</button></div><p class="note">1일씩 이동 경과를 볼 수 있습니다. 실행을 시작하면 이번 10일 동안 경로가 고정됩니다.</p></section><section class="card"><div class="eyebrow">주변 관측</div>${seen.length?`<ul class="roster">${seen.map(x=>`<li><strong>${FACTIONS[x.factionId].name} ${TROOPS[x.troopType]}</strong><span>(${x.tileId}) · 병력 미상</span></li>`).join('')}</ul>`:'<p>현재 보이는 다른 세력 부대가 없습니다.</p>'}${old.map(x=>`<p class="note">${FACTIONS[x.factionId].name} ${TROOPS[x.troopType]} · 마지막 위치 (${x.tileId}), ${x.lastSeen.turn}턴 ${Number((x.lastSeen.tick*.05).toFixed(2))}일째</p>`).join('')}${v.contacts.length?'<p class="note">다른 세력과 접촉하여 부대가 멈췄습니다. 전투는 다음 단계에서 연결합니다.</p>':''}</section><section class="card"><div class="eyebrow">${esc(c.name)} · 태수 ${esc(v.officers[c.governorId].name)}</div><p>인구 ${c.population} · 식량 ${c.foodStock} · 명망 ${v.faction.prestige}</p><div class="actions"><button id="save">진행 저장</button><button id="load">진행 불러오기</button><button id="new">세력 다시 선택</button></div><p class="notice" role="status">${esc(notice)}</p><p class="note">전투 피해와 도시 정산은 아직 적용하지 않습니다.</p></section></aside></div></div>`;
  app.querySelectorAll('[data-army-select],[data-army]').forEach(el=>el.addEventListener('click',()=>{state.ui.selectedArmyId=el.dataset.armySelect??el.dataset.army;renderGame();}));
  app.querySelectorAll('[data-tile]').forEach(el=>el.addEventListener('click',()=>{if(!locked){destination=el.dataset.tile;renderGame();}}));
  app.querySelector('#destination').addEventListener('input',e=>{destination=e.target.value.trim();});
  app.querySelector('#move-form').addEventListener('submit',e=>{e.preventDefault();order('MOVE');});
  app.querySelector('#hold').addEventListener('click',()=>order('HOLD'));
  app.querySelector('#day').addEventListener('click',()=>act(()=>{state=executeTicks(state,Math.min(20,200-state.time.tick));notice='이동과 관측을 갱신했습니다.';}));
  app.querySelector('#turn').addEventListener('click',()=>act(()=>{state=advanceTurn(state);notice='10일간의 이동을 마쳤습니다. 다음 명령을 준비하세요.';}));
  app.querySelector('#save').addEventListener('click',()=>act(()=>{localStorage.setItem(SAVE_KEY,exportSave(state));notice='이동 경과와 관측 기록을 저장했습니다.';}));
  app.querySelector('#load').addEventListener('click',load);
  app.querySelector('#new').addEventListener('click',()=>{state=null;destination='';notice='';renderStart();});
}
renderStart();
loadInputs().then(value=>{inputs=value;renderStart();}).catch(e=>{notice=e.message;renderStart();});
